CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL COLLATE NOCASE, password_hash TEXT NOT NULL, password_salt TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','member')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS players (id TEXT PRIMARY KEY, name TEXT NOT NULL, class TEXT NOT NULL DEFAULT '', race TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', details TEXT NOT NULL DEFAULT '', google_sheet_url TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS xp_entries (id TEXT PRIMARY KEY, player_id TEXT REFERENCES players(id) ON DELETE SET NULL, player_name TEXT NOT NULL, date TEXT NOT NULL, type TEXT NOT NULL, title TEXT NOT NULL, xp INTEGER NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS xp_entries_date ON xp_entries(date DESC);
CREATE INDEX IF NOT EXISTS xp_entries_player ON xp_entries(player_id, date DESC);
CREATE TABLE IF NOT EXISTS login_attempts (ip TEXT NOT NULL, attempted_at TEXT NOT NULL);

